bool isPermutation(const char *a, const char *b) {
    size_t aLen = strlen(a), bLen = strlen(b);
    if (aLen != bLen) return false;
    char *bCopy = strdup(b);
    int found = 0;
    for (size_t i = 0; i < aLen; i++) {
        for (size_t k = 0; k < bLen; k++) {
            if (a[i] == bCopy[k]) {
                found++;
                bCopy[k] = '\xff';
                break;
            }
        }
    }
    free(bCopy);
    return found == (int)aLen;
}

