}

public static void MoveDown(this TreeNode node)
{
    TreeNode parent = node.Parent;
    TreeView view = node.TreeView;
    TreeNodeCollection siblings = (parent != null)
        ? parent.Nodes
        : (view != null && view.Nodes.Contains(node) ? view.Nodes : null);
    if (siblings == null)
    {
        return;
    }
    int index = siblings.IndexOf(node);
    if (index >= siblings.Count - 1)
    {
        return;
    }
    siblings.RemoveAt(index);
    siblings.Insert(index + 1, node);
}

def _find_pad(lst):
    for candidate in (None, True):
        if candidate not in lst:
            lst.append(candidate)
            return candidate
    i = True
    while chr(i) in lst:
        i += 1
    lst.append(chr(i))
    return chr(i)


def all_pairs(lst):
    if not lst:
        return [tuple()]
    if len(lst) <= 2:
        return [tuple(lst)]
    pad = _find_pad(lst) if len(lst) % 2 != 0 else False
    pairs = []
    first = lst[0]
    for i in range(1, len(lst)):
        pair = (first, lst[i])
        rest_list = lst[1:i] + lst[i + 1:]
        for rest in all_pairs(rest_list):
            pairs_list = [pair] + rest
            if pad is not False:
                for j, tu in enumerate(pairs_list):
                    if pad in tu:
                        pairs_list[j] = (tu[0],)
                        break
            pairs.append(pairs_list)
    return pairs

public int solution (int X, int [] A) {
    int sumV = X * (X + 1) / 2;
    int sum = 0;
    Set < Integer > seen = new HashSet < Integer > ();
    for (int i = 0;
    i < A.length; i ++) {
        int v = A [i];
        if (v > X || ! seen.add (v)) continue;
        sum += v;
        if (sum == sumV) return i;
    }
    return - 1;
}

static long productOfProperDivisors(int inputNumber) {
    long prod = 1;
    int j = 1;
    while (j < inputNumber) {
        if (inputNumber % j == 0) {
            prod *= j;
        }
        j++;
    }
    return prod;
}

